import net.neoforged.neoforge.event.server.ServerStartedEvent;
/** Real Survival item placement into private registered27 shapes; no public engine registrations. */
@EventBusSubscriber(modid="vandorlabs")
public final class PropulsionItemChecks {
 private static final java.util.Map<String,NativePropulsionBlock> BLOCKS=new java.util.LinkedHashMap<>();private static final java.util.Map<String,NativePropulsionItem> ITEMS=new java.util.LinkedHashMap<>();private static BlockEntityType<NativePropulsionEntity> TYPE;private static int checks,uses,fault,drops;private static BlockPos dropPos;private static ItemStack dropped;private static final BlockPos BASE=new BlockPos(7524,90,7524),SAVED=BASE.south(8);
 private static String phase(){return System.getProperty("vandorlabs.transmitterPhase","");}private static boolean enabled(){return phase().startsWith("propulsion-item-");}private static void need(boolean yes,String text){checks++;if(!yes)throw new AssertionError("Propulsion item "+text);}
 private static final class FaultItem extends NativePropulsionItem {FaultItem(NativePropulsionBlock block){super(block,new Item.Properties());}@Override protected boolean stage(net.minecraft.world.level.Level world,BlockPos pos,BlockState state){boolean result=super.stage(world,pos,state);if(fault==1)return false;if(fault==2)throw new IllegalStateException("injected propulsion install failure");if(fault==3)world.removeBlockEntity(pos);return result;}@Override protected boolean restore(net.minecraft.world.level.Level world,BlockPos pos,BlockState state){return fault>=2?false:super.restore(world,pos,state);}}
 @SubscribeEvent public static void joined(net.neoforged.neoforge.event.entity.EntityJoinLevelEvent e){if(enabled()&&dropPos!=null&&e.getEntity() instanceof net.minecraft.world.entity.item.ItemEntity item&&item.position().distanceToSqr(Vec3.atCenterOf(dropPos))<16&&item.getItem().getItem() instanceof NativePropulsionItem){drops+=item.getItem().getCount();dropped=item.getItem().copy();}}
 private static ResourceLocation id(String name){return ResourceLocation.fromNamespaceAndPath("vandorlabs","propulsion_item_fixture_"+name);}
 @EventBusSubscriber(modid="vandorlabs",bus=EventBusSubscriber.Bus.MOD)public static final class Registration{@SubscribeEvent public static void register(net.neoforged.neoforge.registries.RegisterEvent e){if(!enabled())return;e.register(Registries.BLOCK,h->{for(var d:PropulsionDefinition.values()){var b=new NativePropulsionBlock(d.id,BlockBehaviour.Properties.of().strength(3),()->TYPE,BLOCKS::get){@Override public BlockEntity newBlockEntity(BlockPos pos,BlockState state){return fault==3?null:super.newBlockEntity(pos,state);}};BLOCKS.put(d.id,b);h.register(id(d.id),b);}});e.register(Registries.ITEM,h->{for(var d:PropulsionDefinition.values())if(d.shape==0){var item=new FaultItem(BLOCKS.get(d.id));ITEMS.put(d.id,item);h.register(id(d.id),item);}});e.register(Registries.BLOCK_ENTITY_TYPE,h->{TYPE=BlockEntityType.Builder.of((p,s)->new NativePropulsionEntity(TYPE,p,s),BLOCKS.values().toArray(NativePropulsionBlock[]::new)).build(null);h.register(id("owner"),TYPE);});}}
 private static CompoundTag config(int profile){var tag=new CompoundTag();switch(profile){case 1:tag.putInt("PropulsionShape",1);break;case 2:tag.putInt("PropulsionShape",2);break;case 3:tag.putInt("PropulsionShape",99);break;case 4:tag.putInt("RedstoneChannel",37);break;case 5:tag.putBoolean("ParticleStream",true);break;default:break;}if(profile<=3){tag.putBoolean("LightInitialized",true);tag.putBoolean("ManualOn",false);tag.putInt("ParticleLevel",3);tag.putBoolean("PropulsionJoin",false);tag.putInt("PropulsionSideTexture",64);}return tag;}
 private static ItemStack held(String id,CompoundTag tag){var stack=new ItemStack(ITEMS.get(id),3);var root=new CompoundTag();root.put("BlockEntityTag",tag.copy());stack.set(DataComponents.CUSTOM_DATA,CustomData.of(root));return stack;}
 private static void write(ServerLevel w){w.getChunkAt(BASE);var player=new net.neoforged.neoforge.common.util.FakePlayer(w,new com.mojang.authlib.GameProfile(java.util.UUID.fromString("9f7dcfcc-752c-47c7-bda9-6f059007bdaa"),"EngineItem"));player.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);player.setPos(BASE.getX()+3.5,BASE.getY(),BASE.getZ()+3.5);float[] hit={Math.nextDown(.5F),.5F,Math.nextUp(.5F)};
  for(String id:ITEMS.keySet())for(var face:Direction.values())for(float u:hit)for(float v:hit)for(int profile=0;profile<6;profile++){
   w.setBlock(BASE,Blocks.AIR.defaultBlockState(),18);var clicked=BASE.relative(face.getOpposite());w.setBlock(clicked,Blocks.STONE.defaultBlockState(),18);var raw=config(profile);var stack=held(id,raw);player.setItemInHand(InteractionHand.MAIN_HAND,stack);double x=u,y=v,z=.625;switch(face){case SOUTH:x=1-u;break;case EAST:z=u;break;case WEST:z=1-u;break;case UP:y=.625;z=v;break;case DOWN:y=.625;z=1-v;break;default:break;}var original=new Vec3(x,y,z);var result=ITEMS.get(id).useOn(new net.minecraft.world.item.context.UseOnContext(player,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atLowerCornerOf(clicked).add(original),face,clicked,false)));need(result.consumesAction()&&stack.getCount()==2,"real Survival use consumes one "+id+"/"+face+"/"+profile);uses++;var expected=PropulsionPlacement.select(PropulsionDefinition.of(id),raw.getInt("PropulsionShape"),face.get3DDataValue(),(float)x,(float)y,(float)z);var state=w.getBlockState(BASE);need(state.getBlock()==BLOCKS.get(expected.id)&&state.getValue(NativePropulsionBlock.FACING)==face,"Source float quadrant/shape selection");var owner=(NativePropulsionEntity)w.getBlockEntity(BASE);var choices=NativePropulsionPlacement.settings(id,expected.id,false,raw).capture(true);need(owner!=null&&!owner.inert()&&owner.settings().equals(choices),"Source fresh-save partial merge including alternate-shape discard");var pick=BLOCKS.get(expected.id).getCloneItemStack(state,new BlockHitResult(Vec3.atCenterOf(BASE),face,BASE,false),w,BASE,player);need(pick.is(ITEMS.get(id))&&NativePropulsionItem.configuration(pick).equals(NativePropulsionPlacement.pick(expected,choices)),"configured pick source key projection");var drop=NativePropulsionItem.drop(BLOCKS.get(expected.id),owner);need(drop.is(ITEMS.get(id))&&(NativePropulsionItem.configuration(drop)==null?NativePropulsionPlacement.drop(expected).isEmpty():NativePropulsionItem.configuration(drop).equals(NativePropulsionPlacement.drop(expected))),"drop retains shape only");w.setBlock(BASE,Blocks.AIR.defaultBlockState(),18);w.setBlock(clicked,Blocks.AIR.defaultBlockState(),18);
  }
  var bad=new CompoundTag();bad.putInt("NativePropulsionSchema",99);var stack=held("rocket_thruster",bad);player.setItemInHand(InteractionHand.MAIN_HAND,stack);w.setBlock(BASE.below(),Blocks.STONE.defaultBlockState(),18);var context=new BlockPlaceContext(player,InteractionHand.MAIN_HAND,stack,new BlockHitResult(Vec3.atLowerCornerOf(BASE),Direction.UP,BASE.below(),false));need(ITEMS.get("rocket_thruster").place(context)==InteractionResult.FAIL&&stack.getCount()==3&&w.isEmptyBlock(BASE),"unsupported item rejects before consumption/world write");
  for(int mode=1;mode<=3;mode++){w.setBlock(BASE,Blocks.AIR.defaultBlockState(),18);fault=mode;var attempt=held("rocket_thruster",config(0));player.setItemInHand(InteractionHand.MAIN_HAND,attempt);boolean threw=false;try{ITEMS.get("rocket_thruster").place(new BlockPlaceContext(player,InteractionHand.MAIN_HAND,attempt,new BlockHitResult(Vec3.atLowerCornerOf(BASE),Direction.UP,BASE.below(),false)));}catch(IllegalStateException expected){threw=true;}finally{fault=0;}if(mode==1)need(attempt.getCount()==3&&w.isEmptyBlock(BASE),"stage false restores previous cell without consuming");else{var recovered=(NativePropulsionEntity)w.getBlockEntity(BASE);need(threw&&attempt.getCount()==2&&recovered!=null&&recovered.inert(),"rollback refusal retains exactly one consumed world owner mode="+mode+" threw="+threw+" count="+attempt.getCount()+" owner="+recovered+" inert="+(recovered!=null&&recovered.inert()));need(recovered.saveWithoutMetadata(w.registryAccess()).contains(NativePropulsionItem.PLACEMENT_RECOVERY),"recovery marker retained");var pick=NativePropulsionItem.pick(BLOCKS.get("rocket_thruster"),recovered);need(NativePropulsionItem.configuration(pick).getCompound(NativePropulsionItem.RECOVERY).contains(NativePropulsionItem.PLACEMENT_RECOVERY),"recovery item keeps failed installation snapshot");}}
  for(boolean creative:new boolean[]{false,true}){w.setBlock(BASE,Blocks.AIR.defaultBlockState(),18);w.setBlock(BASE,BLOCKS.get("rocket_thruster").defaultBlockState(),18);var invalid=config(0);invalid.putInt("NativePropulsionSchema",99);((NativePropulsionEntity)w.getBlockEntity(BASE)).loadWithComponents(invalid,w.registryAccess());player.setGameMode(creative?net.minecraft.world.level.GameType.CREATIVE:net.minecraft.world.level.GameType.SURVIVAL);player.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);dropPos=BASE;drops=0;need(player.gameMode.destroyBlock(BASE)&&drops==1,"inert owner mines to exactly one recovery item creative="+creative);need(NativePropulsionItem.configuration(dropped).getCompound(NativePropulsionItem.RECOVERY).getInt("NativePropulsionSchema")==99,"mined inert item retains original schema");dropPos=null;}
  player.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);
  w.setBlock(SAVED,BLOCKS.get("rocket_thruster_hexagonal").defaultBlockState(),18);var owner=(NativePropulsionEntity)w.getBlockEntity(SAVED);owner.installItem(NativePropulsionEntity.prepareItem(BLOCKS.get("rocket_thruster_hexagonal"),SAVED,owner.getBlockState(),config(0),w.registryAccess()));NativePropulsionService.refresh(owner);w.setChunkForced(SAVED.getX()>>4,SAVED.getZ()>>4,true);
 }
 private static void read(ServerLevel w){w.getChunkAt(SAVED);var owner=(NativePropulsionEntity)w.getBlockEntity(SAVED);NativePropulsionService.refresh(owner);need(owner!=null&&!owner.inert()&&owner.settings().data().sideTexture==64&&owner.settings().data().particleLevel==3&&!owner.visual().powered(),"configured saved owner after complete-process restart");need(NativePropulsionItem.configuration(NativePropulsionItem.drop(BLOCKS.get("rocket_thruster_hexagonal"),owner)).equals(NativePropulsionPlacement.drop(PropulsionDefinition.of("rocket_thruster_hexagonal"))),"restart drop remains shape-only");}
 @SubscribeEvent public static void started(ServerStartedEvent e){if(!enabled())return;try{var w=e.getServer().overworld();if(phase().endsWith("write"))write(w);else read(w);e.getServer().saveEverything(true,true,true);System.out.println("[vandorlabs][propulsion-item] "+(phase().endsWith("write")?"write":"read")+" PASS checks="+checks+" SurvivalUses="+uses);}catch(Throwable failed){System.err.println("[vandorlabs][propulsion-item] FAIL "+failed);failed.printStackTrace();}finally{e.getServer().halt(false);}}
}
